-- BOXHEAD-ZMD(AU)[32+64]-V15.01
-- Do not edit this file. Any change breaks the decoder.
local _kmorit = 65
local _wdibin = 243
local _fkrisc = 95
local _nzappc = ""

local _jjxfnh = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _qouawy(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _ncjidp(d)
	d = d:gsub("[^" .. _jjxfnh .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_jjxfnh:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _vaqtbv = _ncjidp(_nzappc)
local _lqamqq = { _kmorit, _wdibin, _fkrisc }
local _sucmse = {}
for i = 1, #_vaqtbv do
	_sucmse[i] = string.char(_qouawy(_vaqtbv:byte(i), _lqamqq[(i - 1) % 3 + 1]))
end

local _fqwnus = load or loadstring
local _zaamlp, _xecpdg = _fqwnus(table.concat(_sucmse), "=w")
if not _zaamlp then
	gg.alert("Corrupted file: " .. tostring(_xecpdg))
	os.exit()
end
_zaamlp()
